package com.downloadanything.pro;

import android.content.*;import android.database.Cursor;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.core.content.ContextCompat;import java.util.*;

/** Focused storage tools for app downloads, failed jobs, safe temp cleanup and Trash. */
public final class StorageManagerActivity extends AppCompatActivity{
    private int BG,CARD,INPUT,GOLD,TEXT,MUTED,OUTLINE;private boolean ar;private LinearLayout body;private final java.util.concurrent.ExecutorService io=RuntimeExecutors.io();
    @Override protected void onCreate(Bundle b){super.onCreate(b);ar=UiPrefs.isArabic(this);UiPrefs.Palette p=UiPrefs.palette(this);BG=p.bg;CARD=p.card;INPUT=p.input;GOLD=p.gold;TEXT=p.text;MUTED=p.muted;OUTLINE=p.outline;setContentView(ui());refresh();}
    private View ui(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(BG);root.setPadding(dp(10),dp(12),dp(10),dp(10));LinearLayout h=new LinearLayout(this);Button back=btn("←");back.setOnClickListener(v->finish());h.addView(back,new LinearLayout.LayoutParams(dp(48),dp(44)));TextView title=txt(tr("🧹 صيانة التنزيل","🧹 Download maintenance"),21,TEXT);title.setTypeface(Typeface.DEFAULT_BOLD);h.addView(title,new LinearLayout.LayoutParams(0,dp(48),1));root.addView(h);root.addView(txt(tr("أدوات مرتبطة مباشرة بالتنزيل: الملفات الكبيرة، المهام الفاشلة، الملفات المؤقتة والسلة.","Download-only maintenance: large files, failed jobs, temporary files and Trash."),12,MUTED));ScrollView s=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);s.addView(body);root.addView(s,new LinearLayout.LayoutParams(-1,0,1));return root;}
    private void refresh(){body.removeAllViews();body.addView(txt(tr("جارٍ الفحص…","Scanning…"),14,MUTED));io.execute(()->{Stats st=scan();SafeCleanupManager.Report temp=SafeCleanupManager.scan(this);List<TrashStore.Entry> trash=TrashStore.list(this);long trashBytes=0;for(TrashStore.Entry e:trash)trashBytes+=e.size;final long tb=trashBytes;runOnUiThread(()->render(st,temp,trash.size(),tb));});}
    private void render(Stats st,SafeCleanupManager.Report temp,int trash,long trashBytes){body.removeAllViews();body.addView(card(tr("تنزيلات الفيديو والصوت","Video & audio downloads"),st.count+" • "+fmt(st.bytes)+"\n"+tr("ملفات كبيرة (>100 MB): ","Large files (>100 MB): ")+st.largeCount+" • "+fmt(st.largeBytes),()->startActivity(new Intent(this,DownloadsActivity.class)),tr("فتح التنزيلات","Open downloads")));body.addView(card(tr("التنزيلات الفاشلة","Failed downloads"),st.failed+" "+tr("مهمة","jobs"),()->{int n=DownloadQueueStore.requeueState(this,"failed");if(n>0)ContextCompat.startForegroundService(this,new Intent(this,DownloadService.class).putExtra("cmd",DownloadService.CMD_PROCESS));Toast.makeText(this,n+" "+tr("أعيدت للمحاولة","requeued"),Toast.LENGTH_SHORT).show();refresh();},tr("إعادة المحاولة","Retry")));body.addView(card(tr("ملفات عمل مؤقتة","Temporary work files"),temp.folders+" • "+fmt(temp.bytes),()->io.execute(()->{SafeCleanupManager.clean(this);runOnUiThread(()->{Toast.makeText(this,tr("تم التنظيف","Cleaned"),Toast.LENGTH_SHORT).show();refresh();});}),tr("تنظيف","Clean")));body.addView(card(tr("سلة المحذوفات","Trash"),trash+" • "+fmt(trashBytes),()->startActivity(new Intent(this,TrashActivity.class)),tr("فتح السلة","Open Trash")));}
    private Stats scan(){Stats s=new Stats();try{if(Build.VERSION.SDK_INT>=29){Uri base=MediaStore.Downloads.EXTERNAL_CONTENT_URI;String[]p={MediaStore.Downloads.SIZE};String sel=MediaStore.Downloads.RELATIVE_PATH+" LIKE ?";try(Cursor c=getContentResolver().query(base,p,sel,new String[]{"Download/Download Anything/%"},null)){if(c!=null){int z=c.getColumnIndexOrThrow(MediaStore.Downloads.SIZE);while(c.moveToNext()){long n=Math.max(0,c.getLong(z));s.count++;s.bytes+=n;if(n>=100L*1024L*1024L){s.largeCount++;s.largeBytes+=n;}}}}}}catch(Exception ignored){}for(DownloadJob j:DownloadQueueStore.all(this))if(j!=null&&"failed".equals(j.state))s.failed++;return s;}
    private View card(String title,String meta,Runnable action,String actionLabel){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(12),dp(10),dp(12),dp(10));c.setBackground(round(CARD,16));TextView t=txt(title,16,TEXT);t.setTypeface(Typeface.DEFAULT_BOLD);c.addView(t);c.addView(txt(meta,12,MUTED));Button b=btn(actionLabel);b.setOnClickListener(v->action.run());c.addView(b,new LinearLayout.LayoutParams(-1,dp(42)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);c.setLayoutParams(lp);return c;}private static final class Stats{int count,largeCount,failed;long bytes,largeBytes;}
    private Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(TEXT);b.setBackground(round(INPUT,12));return b;}private TextView txt(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);return v;}private GradientDrawable round(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));d.setStroke(dp(1),OUTLINE);return d;}private int dp(int x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}private String tr(String a,String e){return ar?a:e;}private String fmt(long b){return b>=1073741824?String.format(Locale.US,"%.1f GB",b/1073741824d):b>=1048576?String.format(Locale.US,"%.1f MB",b/1048576d):String.format(Locale.US,"%.0f KB",b/1024d);}
}
